insert into public.bedaya_catalog(key,kind,payload,is_demo) values('rules-demo-v1','rules','{"version":"demo-v1","disclaimer":"Fictional demo steps, fees and durations; not verified Jordanian requirements.","steps":[{"key":"profile","title_ar":"تأكيد ملف المشروع (تجريبي)","title_en":"Confirm business profile (demo)","office":"Bedaya demo","documents":["identity","address"],"dependencies":[],"fee":0,"days":1,"online":true},{"key":"registration","title_ar":"التسجيل التجاري (تجريبي)","title_en":"Trade registration (demo)","office":"Demo trade registry","documents":["identity"],"dependencies":["profile"],"fee":20,"days":2,"legalForm":"sole","online":true},{"key":"registration","title_ar":"تسجيل الشركة (تجريبي)","title_en":"Company registration (demo)","office":"Demo companies authority","documents":["identity","partner_details"],"dependencies":["profile"],"fee":50,"days":4,"legalForm":"llc","online":true},{"key":"home_check","title_ar":"فحص مسار العمل المنزلي (تجريبي)","title_en":"Home activity review (demo)","office":"Demo municipality","documents":["address","inspection_consent"],"dependencies":["registration"],"fee":5,"days":2,"premises":"home"},{"key":"shop_check","title_ar":"مراجعة موقع المحل (تجريبي)","title_en":"Shop location review (demo)","office":"Demo municipality","documents":["address"],"dependencies":["registration"],"fee":10,"days":2,"premises":"shop"},{"key":"license","title_ar":"الترخيص المهني (تجريبي)","title_en":"Vocational licensing (demo)","office":"Demo licensing office","documents":["registration","address"],"dependencies":["registration"],"fee":25,"days":3},{"key":"tax","title_ar":"فتح الملف الضريبي (تجريبي)","title_en":"Tax file setup (demo)","office":"Demo tax authority","documents":["registration"],"dependencies":["registration"],"fee":0,"days":1,"online":true},{"key":"social","title_ar":"التأمينات والضمان (تجريبي)","title_en":"Social security review (demo)","office":"Demo social security","documents":["registration"],"dependencies":["registration"],"fee":0,"days":1,"online":true}]}'::jsonb,true) on conflict(key) do nothing;
